<?php
require_once __DIR__.'/../../config/config.php';require_doctor();require_once __DIR__.'/../../includes/doctor_clinical_service.php';$s=new DoctorClinicalService(getDB(),current_user());$pageTitle='Patient Records & Physician Consultations';$error='';$patient=(int)($_GET['patient']??$_POST['patient_user_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify_or_die();try{$s->save($_POST);set_flash('success','Physician encounter saved with author and audit history.');redirect('consultations.php?patient='.$patient);}catch(PDOException $e){error_log('Doctor clinical form: '.$e->getMessage());$error='Clinical data could not be saved.';}catch(RuntimeException|InvalidArgumentException $e){$error=$e->getMessage();}}
$patients=$s->patients(is_string($_GET['search']??'')?($_GET['search']??''):'');$records=[];if($patient){try{$records=$s->records($patient);}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
?>
<!DOCTYPE html><html lang="en"><head><?php include __DIR__.'/../../includes/head.php'; ?></head><body><div class="app-wrapper"><?php include __DIR__.'/../../components/sidebar.php'; ?><div class="main-content"><?php include __DIR__.'/../../components/navbar.php'; ?><main id="mainContent" class="content-area"><h1 class="h4">Patient Records &amp; Physician Consultations</h1><p class="small text-muted">Authorized clinical records. Save a new physician encounter or revise one you authored; nursing documentation remains intact.</p><?php if($error): ?><p class="alert alert-danger" role="alert"><?=e($error)?></p><?php endif; ?><form method="get" class="d-flex gap-2 mb-3"><label for="clinical-search" class="visually-hidden">Search name or institutional ID</label><input id="clinical-search" name="search" class="form-control" placeholder="Search patient name or institutional ID" maxlength="100" value="<?=e($_GET['search']??'')?>"><button class="btn btn-outline-primary">Search</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Patient</th><th>Role</th><th>Identifier</th><th>Records</th></tr></thead><tbody><?php foreach($patients as $p): ?><tr><td><?=e($p['first_name'].' '.$p['last_name'])?></td><td><?=e($p['role'])?></td><td><?=e($p['identifier'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?patient=<?=$p['id']?>">View clinical records</a></td></tr><?php endforeach; ?><?php if(!$patients): ?><tr><td colspan="4">No matching patients. Search returns up to 50 records.</td></tr><?php endif; ?></tbody></table></div>
<?php if($patient): ?><form method="post" class="card p-3 my-3"><?=csrf_field()?><input type="hidden" name="patient_user_id" value="<?=$patient?>"><h2 class="h6">New physician consultation · Patient account #<?=$patient?></h2><?php foreach(['chief_complaint'=>'Chief complaint','diagnosis'=>'Medical findings / diagnosis','treatment'=>'Treatment decision','prescription'=>'Prescription / instructions','remarks'=>'Clinical notes'] as $key=>$label): ?><label for="new-<?=$key?>" class="form-label small mt-2"><?=$label?></label><textarea id="new-<?=$key?>" name="<?=$key?>" class="form-control" maxlength="<?=in_array($key,['chief_complaint','diagnosis'],true)?255:5000?>" <?=$key==='chief_complaint'?'required':''?>></textarea><?php endforeach; ?><button class="btn btn-sm btn-primary mt-3 align-self-start">Save physician encounter</button></form><h2 class="h6">Clinical history</h2><?php foreach($records as $r): ?><details class="card p-3 mb-2"><summary>Consultation #<?=$r['id']?> · <?=e($r['consultation_date'])?> · <?=e($r['chief_complaint'])?></summary><?php if((int)$r['clinician_user_id']===(int)current_user()['id']): ?><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="patient_user_id" value="<?=$patient?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="record_version" value="<?=$r['record_version']?>"><?php foreach(['chief_complaint','diagnosis','treatment','prescription','remarks'] as $key): ?><label class="form-label small" for="record-<?=$r['id']?>-<?=$key?>"><?=e(ucwords(str_replace('_',' ',$key)))?></label><textarea class="form-control mb-2" id="record-<?=$r['id']?>-<?=$key?>" name="<?=$key?>"><?=e($r[$key]??'')?></textarea><?php endforeach; ?><button class="btn btn-sm btn-outline-primary">Save revision</button></form><?php else: ?><dl class="mt-3"><?php foreach(['diagnosis','treatment','prescription','remarks'] as $key): ?><dt><?=e(ucfirst($key))?></dt><dd><?=nl2br(e($r[$key]??'Not recorded'))?></dd><?php endforeach; ?></dl><?php endif; ?></details><?php endforeach; ?><?php endif; ?></main></div></div><?php include __DIR__.'/../../components/footer.php'; ?></body></html>
